import React from 'react';

const SPECIALTY_ICONS = {
  Cardiologist: '❤️',
  Dentist: '🦷',
  Dermatologist: '🧴',
  Neurologist: '🧠',
  Pediatrician: '👶',
  'Orthopedic Surgeon': '🦴',
  Psychiatrist: '🧘',
};

function StarRating({ rating }) {
  const full = Math.floor(rating);
  const half = rating % 1 >= 0.5;
  return (
    <div className="flex items-center gap-1">
      <span className="text-yellow-400 text-sm">
        {'★'.repeat(full)}{half ? '½' : ''}{'☆'.repeat(5 - full - (half ? 1 : 0))}
      </span>
      <span className="text-xs text-gray-500 font-medium">{rating.toFixed(1)}</span>
    </div>
  );
}

export default function DoctorCard({ doctor, onBook, onChat, showToggle, onToggle }) {
  const icon = SPECIALTY_ICONS[doctor.specialization] || '👨‍⚕️';

  return (
    <div className={`bg-white rounded-2xl shadow-sm border p-6 flex flex-col gap-4 transition-shadow duration-200
      ${doctor.isAvailable ? 'border-gray-100 hover:shadow-md' : 'border-gray-200 opacity-70'}`}>

      {/* Header */}
      <div className="flex items-start gap-4">
        <div className="w-14 h-14 rounded-full bg-blue-50 flex items-center justify-center text-2xl flex-shrink-0">
          {icon}
        </div>
        <div className="flex-1 min-w-0">
          <div className="flex items-start justify-between gap-2">
            <h3 className="font-semibold text-gray-900 text-base truncate">{doctor.name}</h3>
            <span className={`text-xs px-2 py-0.5 rounded-full font-medium flex-shrink-0 ${
              doctor.isAvailable ? 'bg-green-100 text-green-700' : 'bg-gray-100 text-gray-500'
            }`}>
              {doctor.isAvailable ? 'Available' : 'Unavailable'}
            </span>
          </div>
          <span className="inline-block mt-1 text-xs font-medium bg-blue-100 text-blue-700 px-2 py-0.5 rounded-full">
            {doctor.specialization}
          </span>
        </div>
      </div>

      {/* Rating + Info */}
      <div className="flex flex-col gap-1.5">
        {doctor.rating > 0 && <StarRating rating={doctor.rating} />}
        <div className="flex gap-4 text-sm text-gray-500">
          <div className="flex items-center gap-1">
            <span>🎓</span>
            <span>{doctor.experience} yrs exp</span>
          </div>
          <div className="flex items-center gap-1">
            <span>📅</span>
            <span className="truncate">{doctor.availability}</span>
          </div>
        </div>
      </div>

      {/* Slots */}
      {doctor.availableSlots?.length > 0 && (
        <div>
          <p className="text-xs text-gray-400 mb-2 font-medium uppercase tracking-wide">Available Slots</p>
          <div className="flex flex-wrap gap-1.5">
            {doctor.availableSlots.map(slot => (
              <span key={slot} className="text-xs bg-green-50 text-green-700 border border-green-200 px-2 py-1 rounded-md">
                {slot}
              </span>
            ))}
          </div>
        </div>
      )}

      {/* Doctor availability toggle */}
      {showToggle && (
        <div className="flex items-center justify-between pt-2 border-t border-gray-50">
          <span className="text-sm text-gray-600">My Availability</span>
          <button
            onClick={onToggle}
            className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors ${
              doctor.isAvailable ? 'bg-green-500' : 'bg-gray-300'
            }`}
          >
            <span className={`inline-block h-4 w-4 transform rounded-full bg-white shadow transition-transform ${
              doctor.isAvailable ? 'translate-x-6' : 'translate-x-1'
            }`} />
          </button>
        </div>
      )}

      {/* Actions — only show for patients */}
      {!showToggle && (
        <div className="flex gap-2 pt-2 border-t border-gray-50">
          <button
            onClick={() => onBook(doctor._id)}
            disabled={!doctor.isAvailable}
            className="flex-1 bg-blue-600 text-white text-sm font-medium py-2 rounded-lg hover:bg-blue-700 transition disabled:opacity-40 disabled:cursor-not-allowed"
          >
            Book Appointment
          </button>
          <button
            onClick={() => onChat(doctor._id)}
            className="px-4 py-2 border border-blue-600 text-blue-600 text-sm font-medium rounded-lg hover:bg-blue-50 transition"
          >
            Chat
          </button>
        </div>
      )}
    </div>
  );
}
